+        fn deadline_probe(&self, _: u64) -> impl FnOnce() -> bool + use<'a> {
+            let certified = self.certified;
+            let due = self.due;
+            move || certified && !due.get()
+        }
+        async fn wait_until(&mut self, _: u64) {
+            self.active.set(true);
+            let _wait = Wait(self.active);
+            core::future::poll_fn(|_| {
